<script setup lang="ts">
import { computed,onMounted,reactive,ref,watch } from 'vue'
import { ClipboardCheck,Plus,Save } from 'lucide-vue-next'
import TaskTabs from '../components/TaskTabs.vue'
import RequirementCoverage from '../components/RequirementCoverage.vue'
import Pager from '../components/Pager.vue'
import DraftNotice from '../components/DraftNotice.vue'
import ConflictNotice from '../components/ConflictNotice.vue'
import HistoryPanel from '../components/HistoryPanel.vue'
import { useConflict,useDraft } from '../drafts'
import { all,api,dateTimeLabel,isProjectReadOnly,messageOf,notify,projectName,query,softDelete,ui } from '../api'
import { queuePrintExport,queueWordExport,queueSnapshotExport } from '../exports'
import { planningLabels,planningValue,requirementStatuses,revisionTasks,type Requirement,type RequirementComparison,type RequirementRevision,type RequirementStatus } from '../planning'
import type { Page,Task } from '../types'
const props=defineProps<{revision:number}>(),emit=defineEmits<{changed:[]}>()
const items=ref<Requirement[]>([]),total=ref(0),offset=ref(0),loading=ref(false),error=ref(''),saving=ref(false),opening=ref(false),exporting=ref(false),editor=ref(false),editing=ref<Requirement>(),tasks=ref<Task[]>([]),taskSearch=ref(''),tasksError=ref(''),tasksLoading=ref(false)
const filters=reactive({project_id:'',status:'',q:''}),applied=ref<Record<string,string|number|undefined>>({})
const form=reactive({project_id:'',title:'',description:'',acceptance_criteria:'',owner:'',source:'',status:'pending' as RequirementStatus,acceptance_note:'',change_note:'',task_ids:[] as string[]})
const revisions=ref<RequirementRevision[]>([]),snapshot=ref<RequirementRevision>(),revisionError=ref(''),revisionLoading=ref(false),from=ref(''),to=ref(''),comparison=ref<RequirementComparison>(),comparing=ref(false),limit=20
const local=useDraft(()=>`requirements:${editing.value?.id||'new'}`,form,()=>editor.value,()=>editing.value?.version),conflict=useConflict()
const busy=computed(()=>saving.value||opening.value||exporting.value),readonly=computed(()=>isProjectReadOnly(form.project_id)||!!editing.value&&ui.projectsLoaded&&!ui.projects.some(p=>p.id===editing.value?.project_id))
const acceptedLocked=computed(()=>!!editing.value&&editing.value.status==='accepted'&&form.status==='accepted')
const visibleTasks=computed(()=>tasks.value.filter(t=>!taskSearch.value.trim()||`${t.wbs_code} ${t.name}`.toLowerCase().includes(taskSearch.value.trim().toLowerCase())))
const unavailableTasks=computed(()=>form.task_ids.filter(id=>!tasks.value.some(t=>t.id===id)))
const valid=computed(()=>!!form.project_id&&!!form.title.trim()&&!!form.description.trim()&&!!form.acceptance_criteria.trim()&&(!editing.value||!!form.change_note.trim())&&(form.status!=='accepted'||!!form.acceptance_note.trim()))
let listRequest=0,entityRequest=0,taskRequest=0,revisionRequest=0
function canLeave(){return !busy.value&&(!editor.value||local.canLeave())}
function assign(item:Requirement){Object.assign(form,{project_id:item.project_id,title:item.title,description:item.description,acceptance_criteria:item.acceptance_criteria,owner:item.owner||'',source:item.source||'',status:item.status,acceptance_note:item.acceptance_note||'',change_note:'',task_ids:[...(item.task_ids||[])]})}
async function load(){const seq=++listRequest;loading.value=true;try{const page=await api<Page<Requirement>>(`/api/requirements?${query({...applied.value,limit,offset:offset.value})}`);if(seq!==listRequest)return;items.value=page.items;total.value=page.total;if(offset.value>=page.total&&offset.value>0){offset.value=0;await load()}}catch(e){if(seq===listRequest)error.value=messageOf(e)}finally{if(seq===listRequest)loading.value=false}}
async function apply(){offset.value=0;applied.value={project_id:filters.project_id,status:filters.status,q:filters.q.trim()};await load()}
async function loadTasks(){const seq=++taskRequest;tasksError.value='';tasks.value=[];if(!form.project_id)return;tasksLoading.value=true;try{const data=await api<Page<Task>>(`/api/projects/${encodeURIComponent(form.project_id)}/tree`);if(seq===taskRequest)tasks.value=data.items}catch(e){if(seq===taskRequest)tasksError.value=messageOf(e)}finally{if(seq===taskRequest)tasksLoading.value=false}}
async function loadRevisions(){const id=editing.value?.id,seq=++revisionRequest;if(!id)return;revisionLoading.value=true;revisionError.value='';try{const data=await all<RequirementRevision>(`/api/requirements/${id}/revisions`);if(seq!==revisionRequest)return;revisions.value=data;const sorted=[...data].sort((a,b)=>a.revision-b.revision);from.value=String(sorted[0]?.revision||'');to.value=String(sorted.at(-1)?.revision||'')}catch(e){if(seq===revisionRequest)revisionError.value=messageOf(e)}finally{if(seq===revisionRequest)revisionLoading.value=false}}
async function create(){if(!canLeave())return;entityRequest++;local.persist();editing.value=undefined;Object.assign(form,{project_id:isProjectReadOnly(filters.project_id)?'':filters.project_id,title:'',description:'',acceptance_criteria:'',owner:ui.operator,source:'',status:'pending',acceptance_note:'',change_note:'',task_ids:[]});editor.value=true;error.value='';conflict.clear();revisions.value=[];snapshot.value=undefined;comparison.value=undefined;taskSearch.value='';await local.reset();await loadTasks()}
async function select(id:string){if(!canLeave())return;const seq=++entityRequest;opening.value=true;error.value='';try{const item=await api<Requirement>(`/api/requirements/${encodeURIComponent(id)}`);if(seq!==entityRequest)return;local.persist();editing.value=item;assign(item);editor.value=true;conflict.clear();snapshot.value=undefined;comparison.value=undefined;taskSearch.value='';await local.reset();await Promise.all([loadTasks(),loadRevisions()])}catch(e){if(seq===entityRequest)error.value=messageOf(e)}finally{if(seq===entityRequest)opening.value=false}}
async function save(){if(busy.value||readonly.value||!valid.value||acceptedLocked.value)return;saving.value=true;error.value='';const payload={...form,task_ids:[...form.task_ids],...(editing.value?{version:editing.value.version}:{})};try{const saved=await api<Requirement>(editing.value?`/api/requirements/${editing.value.id}`:'/api/requirements',{method:editing.value?'PATCH':'POST',body:JSON.stringify(payload)});local.discard();editing.value=saved;assign(saved);conflict.clear();snapshot.value=undefined;comparison.value=undefined;await local.reset();notify(`需求已保存为修订 ${saved.revision}`);emit('changed');await Promise.all([load(),loadRevisions()])}catch(e){error.value=messageOf(e);local.persist();if(editing.value)await conflict.capture(e,`/api/requirements/${editing.value.id}`,payload)}finally{saving.value=false}}
async function reloadConflict(){const remote=conflict.current.value?.remote as unknown as Requirement;if(!remote)return;local.persist();editing.value=remote;assign(remote);conflict.clear();await local.reset();await Promise.all([loadTasks(),loadRevisions()]);error.value='已载入服务器需求，原修改仍保留在浏览器草稿中。'}
async function remove(){if(!editing.value||readonly.value||!canLeave())return;saving.value=true;error.value='';try{if(await softDelete('requirements',editing.value,editing.value.title)){local.discard();editing.value=undefined;editor.value=false;entityRequest++;revisionRequest++;emit('changed');await load()}}catch(e){error.value=messageOf(e);if(editing.value)await conflict.capture(e,`/api/requirements/${editing.value.id}`,form)}finally{saving.value=false}}
async function viewRevision(value:string){if(!editing.value||!value)return;const id=editing.value.id,seq=++revisionRequest;revisionError.value='';try{const result=await api<RequirementRevision>(`/api/requirements/${id}/revisions/${value}`);if(seq===revisionRequest)snapshot.value=result}catch(e){if(seq===revisionRequest)revisionError.value=messageOf(e)}}
async function compare(){if(!editing.value||!from.value||!to.value)return;const id=editing.value.id;comparing.value=true;revisionError.value='';try{const result=await api<RequirementComparison>(`/api/requirements/${id}/revisions/compare?${query({from:from.value,to:to.value})}`);if(editing.value?.id===id)comparison.value=result}catch(e){revisionError.value=messageOf(e)}finally{comparing.value=false}}
async function exportRevision(print=false){if(!snapshot.value||busy.value||local.dirty.value)return;exporting.value=true;revisionError.value='';try{await queueSnapshotExport('requirement_revisions',{id:`${snapshot.value.requirement_id}:${snapshot.value.revision}`,version:1},print?'html':'docx')}catch(e){revisionError.value=messageOf(e)}finally{exporting.value=false}}
async function exportSaved(print=false){if(!editing.value||busy.value||local.dirty.value)return;exporting.value=true;try{if(print)await queuePrintExport('requirements',editing.value);else await queueWordExport('requirements',editing.value)}catch(e){error.value=messageOf(e)}finally{exporting.value=false}}
function openTask(id:string){if(!canLeave())return;editor.value=false;location.hash=`#/tasks?id=${encodeURIComponent(id)}`}
function restoreDraft(){local.restore();void loadTasks()}
function forceDraft(){local.restoreForced();void loadTasks()}
function unlink(id:string){form.task_ids=form.task_ids.filter(t=>t!==id)}
function comparedTaskLabel(id:unknown,side:'from'|'to'){const task=revisionTasks(comparison.value?.[side].snapshot||{}).find(t=>t.id===id);return task?historicalTaskLabel(task):String(id)}
function historicalTaskLabel(task:Record<string,unknown>){return `${task.wbs_code||''} ${task.name||task.id||''}`.trim()}
onMounted(()=>{filters.project_id=ui.projects[0]?.id||'';void apply()});watch(()=>props.revision,()=>void load())
defineExpose({canLeave,openEntity:select})
</script>
<template>
<div class="page-heading"><div><h1>任务与 WBS</h1><p class="page-description">把需求、验收准则与执行任务连起来，保留每次修订。</p></div><button class="button primary" :disabled="busy" @click="create"><Plus :size="16"/>新增需求</button></div><TaskTabs active="requirements"/>
<form class="filter-bar requirement-filters" @submit.prevent="apply"><select v-model="filters.project_id" aria-label="需求所属项目"><option value="">全部项目</option><option v-for="p in ui.projects" :key="p.id" :value="p.id">{{p.name}}</option></select><select v-model="filters.status" aria-label="筛选需求状态"><option value="">全部状态</option><option v-for="(label,value) in requirementStatuses" :key="value" :value="value">{{label}}</option></select><input v-model="filters.q" aria-label="搜索需求" maxlength="200" placeholder="编号、标题或需求内容"/><button class="button subtle" :disabled="loading">查询</button></form>
<div v-if="error" class="error-banner" role="alert">{{error}}</div><p v-if="conflict.error.value" class="form-error" role="alert">{{conflict.error.value}}</p>
<RequirementCoverage :project-id="filters.project_id" :revision="props.revision" :disabled="busy" @requirement="select" @task="openTask"/><div class="worklog-layout requirement-layout"><aside class="surface saved-logs"><div class="section-heading"><h2>需求 <span class="count">{{total}}</span></h2></div><p v-if="loading" class="loading-message">正在读取需求…</p><div v-else-if="!items.length" class="empty-state compact"><ClipboardCheck :size="30"/><p>没有符合条件的需求。先写清需求与验收准则，再关联任务。</p></div><div v-else class="log-list"><button v-for="item in items" :key="item.id" :disabled="busy" :class="{selected:editing?.id===item.id}" @click="select(item.id)"><span>{{item.code}} · 修订 {{item.revision}}</span><strong>{{item.title}}</strong><span>{{requirementStatuses[item.status]}} · {{projectName(item.project_id)}}</span></button></div><Pager :offset="offset" :limit="limit" :total="total" @change="offset=$event;load()"/></aside>
<section class="surface requirement-editor"><template v-if="editor"><div class="section-heading"><div><h2>{{editing?'需求详情':'新增需求'}} <span v-if="local.dirty.value" class="draft-label">未保存</span></h2><p class="input-hint">{{editing?`${editing.code} · 修订 ${editing.revision}`:'保存后生成编号与首个修订'}}<template v-if="readonly"> · 项目只读</template></p></div><div class="row-actions"><button v-if="editing" class="button subtle small" :disabled="busy||local.dirty.value" @click="exportSaved()">导出 Word</button><button v-if="editing" class="button subtle small" :disabled="busy||local.dirty.value" @click="exportSaved(true)">打印 / PDF</button><button v-if="editing&&!readonly" class="button subtle small" :disabled="busy" @click="remove">移入回收站</button><button v-if="!readonly" class="button primary small" form="requirement-form" type="submit" :disabled="busy||!valid||acceptedLocked"><Save :size="15"/>{{saving?'正在保存…':'保存需求'}}</button></div></div>
<div class="requirement-notices"><DraftNotice :value="local.available.value" :values="local.values.value" :error="local.storageError.value" :recovery="local.recovery.value" @select="local.select" @restore="restoreDraft" @force="forceDraft" @cancel-recovery="local.clearRecovery" @discard="local.discardAvailable"/><ConflictNotice :value="conflict.current.value" @keep="local.persist();conflict.clear()" @reload="reloadConflict"/></div>
<form id="requirement-form" class="requirement-fields" @submit.prevent="save"><fieldset :disabled="busy||readonly"><div class="form-row"><label>所属项目 <span class="required">*</span><select v-model="form.project_id" required :disabled="!!editing" @change="form.task_ids=[];loadTasks()"><option value="" disabled>选择项目</option><option v-for="p in ui.projects" :key="p.id" :value="p.id" :disabled="isProjectReadOnly(p.id)&&p.id!==form.project_id">{{p.name}}</option></select></label><label>状态<select v-model="form.status" aria-label="需求状态"><option v-for="(label,value) in requirementStatuses" :key="value" :value="value">{{label}}</option></select></label></div><p v-if="acceptedLocked" class="requirement-help">此需求已验收。需要修改时，请先将状态改为待处理、进行中或已作废，并填写修订原因。</p><p v-else class="input-hint">任务完成不会自动验收需求；验收时需填写验收说明。</p><fieldset :disabled="acceptedLocked"><label>需求标题 <span class="required">*</span><input v-model="form.title" maxlength="500" required/></label><div class="form-row"><label>负责人<input v-model="form.owner" maxlength="100"/></label><label>来源<input v-model="form.source" maxlength="2000" placeholder="客户意见、会议或原始文档等"/></label></div><label>需求说明 <span class="required">*</span><textarea v-model="form.description" rows="6" maxlength="200000" required placeholder="说明需要解决的问题、范围和预期行为"/></label><label>验收准则 <span class="required">*</span><textarea v-model="form.acceptance_criteria" rows="4" maxlength="20000" required placeholder="写下可以具体核对的结果或条件"/></label><div class="requirement-task-heading"><h3>关联任务</h3><span class="input-hint">已选 {{form.task_ids.length}} 项</span></div><p v-if="tasksError" class="form-error" role="alert">{{tasksError}} <button type="button" class="text-button" @click="loadTasks">重新读取</button></p><p v-else-if="tasksLoading" class="input-hint">正在读取完整项目任务…</p><template v-else><input v-model="taskSearch" aria-label="筛选关联任务" placeholder="按 WBS 或名称筛选任务"/><div class="requirement-task-list"><label v-for="task in visibleTasks" :key="task.id"><input v-model="form.task_ids" type="checkbox" :value="task.id"/><span :style="{paddingLeft:`${(task.depth||0)*12}px`}">{{task.wbs_code}} {{task.name}}</span></label><p v-if="!visibleTasks.length" class="input-hint">{{form.project_id?'没有符合条件的可关联任务。':'先选择项目。'}}</p></div></template><div v-if="unavailableTasks.length&&!tasksLoading" class="requirement-help"><p>以下关联任务已回收或不可用。历史修订仍保留当时的任务快照。</p><div v-for="id in unavailableTasks" :key="id">{{editing?.linked_tasks?.find(t=>t.id===id)?.name||id}} <button type="button" class="text-button" @click="unlink(id)">移除关联</button></div></div><label>验收说明 <span v-if="form.status==='accepted'" class="required">*</span><textarea v-model="form.acceptance_note" rows="3" maxlength="20000" :required="form.status==='accepted'" placeholder="记录验收结果与依据，设为已验收时必填"/></label></fieldset><label>修订原因 <span v-if="editing" class="required">*</span><textarea v-model="form.change_note" rows="2" maxlength="2000" :required="!!editing" placeholder="说明此次调整原因，已有需求每次保存均需填写"/></label></fieldset></form><div class="editor-footer">{{editing?'数据版本 '+editing.version:'尚未保存到数据库'}}<span>修订保留原需求与任务快照</span></div>
<section v-if="editing" class="requirement-revisions"><div class="section-heading"><h2>修订记录</h2></div><p v-if="revisionLoading" class="loading-message">正在读取修订…</p><p v-if="revisionError" class="form-error" role="alert">{{revisionError}}</p><div class="revision-tools"><label>查看历史修订<select aria-label="查看需求历史修订" :value="snapshot?.revision||''" @change="viewRevision(($event.target as HTMLSelectElement).value)"><option value="" disabled>选择修订</option><option v-for="r in revisions" :key="r.revision" :value="r.revision">修订 {{r.revision}} · {{dateTimeLabel(r.created_at)}}</option></select></label><form class="revision-compare-form" @submit.prevent="compare"><label>原修订<select v-model="from"><option v-for="r in revisions" :key="r.revision" :value="String(r.revision)">{{r.revision}}</option></select></label><label>新修订<select v-model="to"><option v-for="r in revisions" :key="r.revision" :value="String(r.revision)">{{r.revision}}</option></select></label><button class="button subtle small" :disabled="comparing||!from||!to">{{comparing?'比较中…':'比较修订'}}</button></form></div>
<div v-if="snapshot" class="requirement-snapshot"><div class="snapshot-heading"><h3>修订 {{snapshot.revision}} · 只读快照</h3><div class="row-actions"><button type="button" class="button subtle small" :disabled="busy||local.dirty.value" @click="exportRevision()">导出此修订 Word</button><button type="button" class="button subtle small" :disabled="busy||local.dirty.value" @click="exportRevision(true)">打印此修订 / PDF</button></div></div><p v-if="local.dirty.value" class="input-hint">当前编辑内容尚未保存，请先保存或恢复数据库内容，再导出此历史修订。</p><p class="input-hint">{{snapshot.created_by}} · {{dateTimeLabel(snapshot.created_at)}} · {{snapshot.change_note}}</p><dl><template v-for="key in ['title','description','acceptance_criteria','owner','source','status','acceptance_note']" :key="key"><dt>{{planningLabels[key]}}</dt><dd>{{key==='status'?requirementStatuses[snapshot.snapshot[key] as RequirementStatus]:planningValue(snapshot.snapshot[key])}}</dd></template></dl><h4>当时关联的任务</h4><ul v-if="revisionTasks(snapshot.snapshot).length"><li v-for="(task,i) in revisionTasks(snapshot.snapshot)" :key="String(task.id||i)">{{historicalTaskLabel(task)}}<span v-if="task.deleted_at">（已回收）</span></li></ul><p v-else class="input-hint">无关联任务。</p><details><summary>快照 SHA-256</summary><code>{{snapshot.hash}}</code></details></div>
<div v-if="comparison" class="requirement-comparison"><h3>修订 {{comparison.from.revision}} → {{comparison.to.revision}}</h3><div v-if="comparison.fields.length" class="table-scroll"><table><thead><tr><th>字段</th><th>原修订</th><th>新修订</th></tr></thead><tbody><tr v-for="field in comparison.fields" :key="field.field"><td>{{planningLabels[field.field]||field.field}}</td><td>{{planningValue(field.before)}}</td><td>{{planningValue(field.after)}}</td></tr></tbody></table></div><p>任务关联：新增 {{comparison.task_links.added.length}} 项 · 移除 {{comparison.task_links.removed.length}} 项</p><ul v-if="comparison.task_links.added.length"><li v-for="id in comparison.task_links.added" :key="String(id)">新增：{{comparedTaskLabel(id,'to')}}</li></ul><ul v-if="comparison.task_links.removed.length"><li v-for="id in comparison.task_links.removed" :key="String(id)">移除：{{comparedTaskLabel(id,'from')}}</li></ul><p v-if="!comparison.changed" class="input-hint">两次修订没有内容差异。</p></div></section><HistoryPanel v-if="editing" kind="requirements" :id="editing.id" :revision="editing.version"/></template><div v-else class="empty-state editor-empty"><ClipboardCheck :size="38"/><h2>让需求有明确的验收依据</h2><p>从左侧选择需求，或新增一条需求并关联项目任务。</p><button class="button primary" @click="create">新增需求</button></div></section></div>
</template>
<style scoped>.log-list button{display:flex;flex-direction:column;align-items:flex-start;gap:5px;text-align:left}.log-list strong{font-size:13px;line-height:1.7;overflow-wrap:anywhere}.log-list button>span{font-size:11px;line-height:1.6;overflow-wrap:anywhere}
.requirement-filters{flex-wrap:wrap}.requirement-filters input{flex:1;min-width:170px}.requirement-layout{align-items:start}.requirement-editor{min-width:0}.requirement-editor>.section-heading{align-items:flex-start}.requirement-editor .row-actions{flex-wrap:wrap;justify-content:flex-end}.requirement-fields{padding:20px 22px}.requirement-fields label{margin-bottom:15px}.requirement-fields textarea{line-height:1.8;resize:vertical}.requirement-fields fieldset{min-width:0}.requirement-notices:has(>*){padding:0 18px}.requirement-help{background:#f2f6fd;border:1px solid #dce7f6;padding:12px;font-size:12px;line-height:1.8;margin:12px 0 16px}.requirement-task-heading{display:flex;align-items:center;justify-content:space-between;margin:18px 0 10px}.requirement-task-list{max-height:240px;overflow:auto;border:1px solid var(--border);margin:8px 0 16px;border-radius:4px}.requirement-task-list label{display:flex;align-items:flex-start;gap:9px;padding:9px 12px;border-bottom:1px solid var(--border);margin:0;font-size:12px;line-height:1.7}.requirement-task-list label:last-child{border:0}.requirement-task-list input{width:14px;min-height:14px;margin-top:3px;flex-shrink:0}.requirement-task-list>.input-hint{padding:12px}.requirement-revisions{border-top:1px solid var(--border)}.revision-tools{padding:16px 20px;display:flex;gap:18px;flex-wrap:wrap;align-items:flex-end}.revision-tools label{font-size:12px;margin:0}.revision-compare-form{display:flex;gap:10px;align-items:flex-end}.revision-compare-form select{min-width:60px}.snapshot-heading{display:flex;align-items:flex-start;justify-content:space-between;gap:12px;flex-wrap:wrap}.requirement-snapshot,.requirement-comparison{padding:18px 20px;border-top:1px solid var(--border)}.requirement-snapshot dl{display:grid;grid-template-columns:85px minmax(0,1fr);gap:12px;font-size:12px;line-height:1.8;margin:16px 0}.requirement-snapshot dt{color:var(--muted)}.requirement-snapshot dd{white-space:pre-wrap;overflow-wrap:anywhere;margin:0}.requirement-snapshot ul{padding-left:20px;line-height:1.9;font-size:12px}.requirement-snapshot code{display:block;overflow-wrap:anywhere;font-size:11px;margin-top:8px}.requirement-comparison h3{margin-bottom:14px}.requirement-comparison td{white-space:pre-wrap;overflow-wrap:anywhere;min-width:120px}.requirement-comparison>p{font-size:12px;margin-top:12px}.requirement-editor .editor-footer{margin:0}.log-list strong{line-height:1.7;overflow-wrap:anywhere}@media(max-width:700px){.requirement-editor>.section-heading{flex-direction:column;gap:12px}.requirement-editor .row-actions{justify-content:flex-start}.requirement-fields{padding:18px 16px}.requirement-filters select:first-child{width:100%}.revision-tools{padding:16px}.requirement-snapshot dl{grid-template-columns:1fr;gap:5px}.requirement-snapshot dd{margin-bottom:8px}}
</style>
